def parse_country(header):
    if not header:
        return None
    h=str(header)
    if h.startswith('Czechia'):
        return 'Czechia'
    if ':' in h:
        return h.split(':')[0].strip()
    return h.split()[0].strip()

countries_total=[]
for c in range(3, ws_total.max_column+1):
    v=ws_total.cell(row,c).value
    if v is not None:
        country=parse_country(headers[c-1])
        countries_total.append(country)

print(countries_total)
